    # redirect it into horizontal sweeps in the intervening open rows.
    holes_by_row = [
        (r, [c for c, v in enumerate(grid[r]) if v == 0])
        for r in range(r0 + 1, h) if any(v == 8 for v in grid[r])
    ]
    active = {c0}
    prev = r0

    for wall, holes in holes_by_row:
        if not holes:
            break
        # Sweep across the open row before the obstacle, bounded by the
        # leftmost and rightmost accessible openings/current beams.
        lo = min(active | set(holes))
        hi = max(active | set(holes))
        for c in range(lo, hi + 1):
            if grid[wall - 1][c] == 0 or grid[wall - 1][c] == 2:
                out[wall - 1][c] = 2
        for c in holes:
            out[wall][c] = 2
        active = set(holes)
        prev = wall

    # Continue any surviving vertical path through the blank area below.
    for c in active:
        for r in range(prev + 1, h):
            if grid[r][c] != 8:
                out[r][c] = 2
    return out
